import{_ as s,c as n,o as a,aN as e}from"./chunks/framework.DUf1V_IZ.js";const c=JSON.parse('{"title":"Zero-shot 与 Few-shot","description":"","frontmatter":{"date":"2026-07-31T15:30:00.000Z","title":"Zero-shot 与 Few-shot","permalink":"/pages/z0f5h0","categories":["AI"]},"headers":[],"relativePath":"AI/08.提示学习/Zero-shot与Few-shot.md","filePath":"AI/08.提示学习/Zero-shot与Few-shot.md","lastUpdated":1785479576000}'),o={name:"AI/08.提示学习/Zero-shot与Few-shot.md"};function r(l,t,i,p,d,h){return a(),n("div",null,[...t[0]||(t[0]=[e(`<h1 id="zero-shot-与-few-shot" tabindex="-1">Zero-shot 与 Few-shot <a class="header-anchor" href="#zero-shot-与-few-shot" aria-label="Permalink to &quot;Zero-shot 与 Few-shot&quot;">​</a></h1><h2 id="一、它们是什么-不重新训练-也能-教-模型" tabindex="-1">一、它们是什么：不重新训练，也能&quot;教&quot;模型 <a class="header-anchor" href="#一、它们是什么-不重新训练-也能-教-模型" aria-label="Permalink to &quot;一、它们是什么：不重新训练，也能&quot;教&quot;模型&quot;">​</a></h2><p>传统上要让模型学会一个新任务，得<strong>微调（fine-tuning）</strong>——改权重、跑训练。但大模型时代出现了一种更轻量的用法：<strong>不碰权重，只靠 Prompt 就把任务说清楚</strong>。其中两类最典型：</p><ul><li><strong>Zero-shot（零样本）</strong>：一句话描述任务，不给任何示例，直接让模型做。</li><li><strong>Few-shot（少样本 / 上下文学习 ICL）</strong>：在 Prompt 里塞几个<strong>示范（输入→输出对）</strong>，让模型&quot;照葫芦画瓢&quot;。</li></ul><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>           任务描述（Instruction）</span></span>
<span class="line"><span>Zero-shot  ───────────────────────────────▶ 模型直接输出</span></span>
<span class="line"><span>           + 几个示范（Example 1~k）</span></span>
<span class="line"><span>Few-shot   ───────────────────────────────▶ 模型模仿示范输出</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><blockquote><p>记忆：<strong>Zero-shot 是&quot;你告诉我规则&quot;，Few-shot 是&quot;我给你几个例子，你照着做&quot;。</strong></p></blockquote><hr><h2 id="二、逐一拆解" tabindex="-1">二、逐一拆解 <a class="header-anchor" href="#二、逐一拆解" aria-label="Permalink to &quot;二、逐一拆解&quot;">​</a></h2><h3 id="_1-zero-shot-零样本" tabindex="-1">1. Zero-shot（零样本） <a class="header-anchor" href="#_1-zero-shot-零样本" aria-label="Permalink to &quot;1. Zero-shot（零样本）&quot;">​</a></h3><p>不给任何示例，仅用自然语言描述任务，依赖模型在预训练/指令微调中已掌握的知识来完成。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请把下面这句话翻译成英文：</span></span>
<span class="line"><span>&quot;今天天气真好。&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>→ 模型输出：The weather is nice today.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><ul><li>模型<strong>从没在这个任务上&quot;训练&quot;过样本</strong>，靠的是预训练学到的语言能力和世界知识。</li><li>适合模型&quot;本来就懂&quot;的常识性、通用任务（翻译、分类、摘要、问答等）。</li></ul><h3 id="_2-one-shot-few-shot-单-少样本" tabindex="-1">2. One-shot / Few-shot（单/少样本） <a class="header-anchor" href="#_2-one-shot-few-shot-单-少样本" aria-label="Permalink to &quot;2. One-shot / Few-shot（单/少样本）&quot;">​</a></h3><p>在 Prompt 里先给 <strong>1 个（one-shot）或 k 个（few-shot）示范</strong>，再给真实问题。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>示例1：</span></span>
<span class="line"><span>输入：苹果</span></span>
<span class="line"><span>输出：水果</span></span>
<span class="line"><span>示例2：</span></span>
<span class="line"><span>输入：胡萝卜</span></span>
<span class="line"><span>输出：蔬菜</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span>现在请分类：</span></span>
<span class="line"><span>输入：老虎</span></span>
<span class="line"><span>输出：</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><ul><li>模型看到示范的&quot;格式&quot;和&quot;模式&quot;后，会<strong>模仿</strong>生成同构的输出（这里是&quot;动物&quot;）。</li><li>多出来的那几个示范，只是拼在 Context 里，<strong>模型权重完全不变</strong>——这是&quot;上下文学习（In-Context Learning, ICL）&quot;。</li><li>k 一般取 2~5 个最常用；极少情况下 1 个（one-shot）也够。</li></ul><h3 id="_3-为什么-llm-能-看例子就学会" tabindex="-1">3. 为什么 LLM 能&quot;看例子就学会&quot; <a class="header-anchor" href="#_3-为什么-llm-能-看例子就学会" aria-label="Permalink to &quot;3. 为什么 LLM 能&quot;看例子就学会&quot;&quot;">​</a></h3><p>关键在 <strong>ICL（In-Context Learning）</strong>：大模型通过注意力机制（Attention），能把 Prompt 里前面的示范&quot;记住&quot;并当作当前预测的隐式条件。相当于在<strong>不更新参数</strong>的前提下，用上下文临时&quot;构造&quot;出一条推理路径。</p><blockquote><p>直觉：Few-shot 不是让模型&quot;现学新知识&quot;，而是<strong>帮模型把已会的能力用对的格式/角度激活出来</strong>。</p></blockquote><hr><h2 id="三、对比一览" tabindex="-1">三、对比一览 <a class="header-anchor" href="#三、对比一览" aria-label="Permalink to &quot;三、对比一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>是否给示例</th><th>权重是否改变</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>Zero-shot</strong></td><td>0 个</td><td>否</td><td>通用、常识性任务；快速试水</td></tr><tr><td><strong>One-shot</strong></td><td>1 个</td><td>否</td><td>格式/风格需要锚定一下</td></tr><tr><td><strong>Few-shot</strong></td><td>k 个（通常 2~5）</td><td>否</td><td>任务特殊、格式复杂、零样本效果差</td></tr><tr><td><strong>Fine-tuning</strong></td><td>大量标注数据</td><td><strong>是</strong>（改权重）</td><td>稳定、低成本、可批量、领域深度定制</td></tr></tbody></table><hr><h2 id="四、怎么写好-few-shot-示范" tabindex="-1">四、怎么写好 Few-shot 示范 <a class="header-anchor" href="#四、怎么写好-few-shot-示范" aria-label="Permalink to &quot;四、怎么写好 Few-shot 示范&quot;">​</a></h2><p>Few-shot 的效果<strong>质量 &gt; 数量</strong>，示范没写好反而有害。几条经验：</p><ol><li><strong>格式严格一致</strong>：示范与真实问题的输入/输出结构要完全相同（分隔符、字段名、顺序都别变），否则模型会&quot;学歪&quot;。</li><li><strong>示范要相关</strong>：挑和真实任务分布相近的例子，比随便堆 10 个不相关的强得多。</li><li><strong>数量适中</strong>：2~5 个通常足够；太多会占用 Context Window，还可能引入噪声与偏见。</li><li><strong>标签均衡</strong>：若分类任务，示范里各类别尽量均衡，避免模型偏向&quot;多数类&quot;。</li><li><strong>顺序留意</strong>：模型对<strong>最后一个示范</strong>有偏好（倾向重复其标签/格式），重要模式放后面或均衡安排。</li><li><strong>指令 + 示范不冲突</strong>：System Prompt 的全局规则如果和示范矛盾，模型可能混乱。</li></ol><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>【好的 few-shot：格式统一、类别均衡】</span></span>
<span class="line"><span>评论：这家店服务态度极差，再也不来了。 → 负面</span></span>
<span class="line"><span>评论：物流很快，包装也很用心。         → 正面</span></span>
<span class="line"><span>评论：东西还行，没什么惊喜。           → 中性</span></span>
<span class="line"><span>评论：客服直接不理人，气死。           → ？</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><hr><h2 id="五、与-fine-tuning-微调-怎么选" tabindex="-1">五、与 Fine-tuning（微调）怎么选 <a class="header-anchor" href="#五、与-fine-tuning-微调-怎么选" aria-label="Permalink to &quot;五、与 Fine-tuning（微调）怎么选&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>Few-shot（Prompt）</th><th>Fine-tuning（微调）</th></tr></thead><tbody><tr><td>改不改权重</td><td>不改</td><td>改</td></tr><tr><td>数据需求</td><td>几个示例即可</td><td>成百上千标注样本</td></tr><tr><td>成本</td><td>低（只写 Prompt）</td><td>高（训练+算力）</td></tr><tr><td>稳定性</td><td>受示例/顺序影响，偶有波动</td><td>稳定、可控</td></tr><tr><td>迭代速度</td><td>秒级（改话术）</td><td>慢（重训）</td></tr><tr><td>适合</td><td>快速验证、长尾/临时任务</td><td>大规模、稳定上线的业务</td></tr></tbody></table><p>经验法则：<strong>先用 Zero-shot 试，不行加 Few-shot，还不行/要稳定批量再做微调。</strong></p><hr><h2 id="六、常见坑" tabindex="-1">六、常见坑 <a class="header-anchor" href="#六、常见坑" aria-label="Permalink to &quot;六、常见坑&quot;">​</a></h2><p><strong>坑 1：位置偏见（Recency Bias）</strong> 模型容易模仿<strong>最后一个示范</strong>的标签/格式。若最后一个是&quot;正面&quot;，即使新输入是负面，也可能被带偏。对策：均衡放置、关键示范靠后、或在指令里强调&quot;按内容判断&quot;。</p><p><strong>坑 2：多数类偏见（Majority Label Bias）</strong> 示范里某类出现最多，模型倾向直接输出该类。对策：类别示范尽量均衡。</p><p><strong>坑 3：顺序敏感</strong> 同一批示范，顺序不同结果可能不同。对策：固定顺序、多跑几次取稳。</p><p><strong>坑 4：与指令冲突</strong> System Prompt 说&quot;只输出 JSON&quot;，示范却给了自然语言，模型会混乱。对策：示范严格遵守最终要求的格式。</p><p><strong>坑 5：吞掉 Context</strong> 示范太长/太多，挤占上下文窗口，反而影响主干任务。对策：精简示范，留足空间给真实输入。</p><hr><h2 id="七、适用场景速查" tabindex="-1">七、适用场景速查 <a class="header-anchor" href="#七、适用场景速查" aria-label="Permalink to &quot;七、适用场景速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>推荐</th></tr></thead><tbody><tr><td>翻译、通用问答、摘要</td><td>Zero-shot 起步</td></tr><tr><td>特定输出格式（JSON / 特定标签）</td><td>Zero-shot + 明确格式要求，必要时 One-shot 锚定</td></tr><tr><td>小众分类、特殊领域口径</td><td>Few-shot（2~5 个贴近业务的示范）</td></tr><tr><td>需要长期稳定、低成本、大批量化</td><td>Fine-tuning</td></tr><tr><td>临时/一次性任务</td><td>Few-shot 足矣，不必训练</td></tr></tbody></table><hr><h2 id="八、一句话总结" tabindex="-1">八、一句话总结 <a class="header-anchor" href="#八、一句话总结" aria-label="Permalink to &quot;八、一句话总结&quot;">​</a></h2><ul><li><strong>Zero-shot</strong>：靠预训练+指令微调学到的&quot;常识&quot;，不给例子直接做。</li><li><strong>Few-shot（ICL）</strong>：在 Context 里给几个示范，模型不改权重、临时&quot;模仿&quot;完成。</li><li>三者递进：<strong>Zero-shot 试水 → Few-shot 提效 → Fine-tuning 沉淀</strong>。</li><li>写好 Few-shot 的关键：<strong>格式一致、示例相关、类别均衡、数量适中</strong>。</li></ul><blockquote><p>口诀：<strong>零样本凭本事，少样本给样子；改格式不动权重，示范写对才像样。</strong></p></blockquote>`,45)])])}const b=s(o,[["render",r]]);export{c as __pageData,b as default};
